from collections import deque

def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = g.copy()
    green = [(int(y), int(x)) for y, x in zip(*np.where(g == 3))]
    red = set((int(y), int(x)) for y, x in zip(*np.where(g == 2)))
    gaxis = [(0, 1), (0, -1)] if len({c[0] for c in green}) == 1 else [(1, 0), (-1, 0)]
    raxis = {(0, 1), (0, -1)} if len({c[0] for c in red}) == 1 else {(1, 0), (-1, 0)}

    def ok(y, x):
        return 0 <= y < H and 0 <= x < W and g[y, x] == bg

    def slide(p, d):
        cells = [p]
        while ok(p[0] + d[0], p[1] + d[1]):
            p = (p[0] + d[0], p[1] + d[1])
            cells.append(p)
        return cells

    q = deque()
    seen = set()
    for d in gaxis:
        end = max(green, key=lambda c: c[0] * d[0] + c[1] * d[1])
        s = (end[0] + d[0], end[1] + d[1])
        if ok(*s):
            q.append((s, d, []))
    found = None
    while q:
        s, d, legs = q.popleft()
        if (s, d) in seen:
            continue
        seen.add((s, d))
        cells = slide(s, d)
        legs2 = legs + [(d, cells)]
        last = cells[-1]
        if d in raxis and (last[0] + d[0], last[1] + d[1]) in red:
            found = legs2
            break
        for nd in ([(1, 0), (-1, 0)] if d[0] == 0 else [(0, 1), (0, -1)]):
            n = (last[0] + nd[0], last[1] + nd[1])
            if ok(*n):
                q.append((n, nd, legs2))
    if found is None:
        emit(out, "No connecting path found; grid unchanged.")
        return out
    for d, cells in found:
        for p in cells:
            out[p] = 3
        emit(out.copy(), f"Slide a green leg in direction {d} for {len(cells)} cells until blocked, then turn.")
    emit(out, "The green corridor now connects the green segment to the red segment.")
    return out
